.ds-example-input { font-family: "SF Pro Display", "PingFang SC", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: var(--text, #21463a); font-size: 15px; line-height: 1.6; }.ds-example-input .ds-field { display: grid; gap: 8px; }.ds-example-input label { color: #42623c; font-size: 13px; font-weight: 500; }.ds-example-input input { font: inherit; width: 100%; min-width: 0; min-height: 48px; padding: 11px 13px; border: 1px solid #ccd9c5; border-radius: 6px; background: var(--input, #fffefa); color: #294c32; caret-color: #315d35; line-height: 1.5; }.ds-example-input input:hover { border-color: #a3ba96; }.ds-example-input input:focus { outline: 2px solid #739362; outline-offset: 2px; }.ds-example-input input::placeholder { color: var(--muted, #58714f); opacity: 1; }.ds-example-input input[aria-invalid="true"] { border-color: #b06d58; }.ds-example-input :focus-visible { outline: 2px solid #547d52; outline-offset: 3px; }
@media (max-width: 600px) { .ds-example-input input { font-size: 16px; padding: 11px 12px; } }
@media (prefers-reduced-motion: reduce) { .ds-example-input *, .ds-example-input *::before, .ds-example-input *::after { transition: none !important; animation: none !important; } }

.ds-example-status-online { font-family: "SF Pro Display", "PingFang SC", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: var(--text, #21463a); font-size: 15px; line-height: 1.6; }.ds-example-status-online .ds-status { display: inline-flex; align-items: center; justify-content: center; gap: 7px; font-size: 11px; line-height: 1.5; font-weight: 550; white-space: nowrap; width: 67px; padding: 5px 9px; border: 1px solid #dbe3d4; border-radius: 4px; color: #5b7051; background: #f1f4ec; }.ds-example-status-online .ds-status::before { content: ""; width: 5px; height: 5px; flex: none; border-radius: 50%; background: currentColor; }.ds-example-status-online .ds-status.ds-online { background: #e9f0de; border-color: #c2d7b8; color: #426f45; }.ds-example-status-online :focus-visible { outline: 2px solid #547d52; outline-offset: 3px; }
@media (max-width: 600px) { .ds-example-status-online .ds-status { width: 55px; font-size: 10px; gap: 4px; padding: 3px 6px; } .ds-example-status-online .ds-status::before { width: 4px; height: 4px; } }
@media (prefers-reduced-motion: reduce) { .ds-example-status-online *, .ds-example-status-online *::before, .ds-example-status-online *::after { transition: none !important; animation: none !important; } }

.ds-example-panel { font-family: "SF Pro Display", "PingFang SC", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: var(--text, #21463a); font-size: 15px; line-height: 1.6; }.ds-example-panel .ds-panel { border-radius: var(--radius, 12px); overflow: hidden; background: var(--paper, #fbfcf7); }.ds-example-panel .ds-panel-head { padding: 30px 32px; background: var(--pine, #214d3c); color: #f2f4e7; }.ds-example-panel .ds-panel-head .ds-subtext { color: #bed0b9; font-size: 13px; line-height: 1.7; margin-top: 9px; }.ds-example-panel .ds-panel-body { padding: 28px 32px 32px; }.ds-example-panel h1 { margin: 0; font-size: 32px; line-height: 1.3; font-weight: 650; letter-spacing: -.03em; text-wrap: balance; }.ds-example-panel p { margin: 0; }.ds-example-panel .ds-subtext { color: var(--muted, #58714f); font-size: 13px; line-height: 1.8; }.ds-example-panel :focus-visible { outline: 2px solid #547d52; outline-offset: 3px; }
@media (max-width: 600px) { .ds-example-panel .ds-panel-head { padding: 25px; } .ds-example-panel .ds-panel-head h1 { font-size: 29px; } .ds-example-panel .ds-panel-body { padding: 24px; } }
@media (prefers-reduced-motion: reduce) { .ds-example-panel *, .ds-example-panel *::before, .ds-example-panel *::after { transition: none !important; animation: none !important; } }

.ds-example-node-row { font-family: "SF Pro Display", "PingFang SC", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: var(--text, #21463a); font-size: 15px; line-height: 1.6; }.ds-example-node-row .ds-nodes { list-style: none; padding: 0; margin: 0; }.ds-example-node-row .ds-node { display: grid; grid-template-columns: minmax(0, 1fr) 110px 140px 104px; column-gap: 24px; align-items: center; padding: 25px 14px; border-bottom: 1px solid #e0e7db; }.ds-example-node-row .ds-node:last-child { border-bottom: 0; }.ds-example-node-row .ds-node-main { display: flex; align-items: center; gap: 18px; min-width: 0; }.ds-example-node-row .ds-node-icon { width: 38px; display: flex; justify-content: center; color: #658873; flex: none; }.ds-example-node-row .ds-node-title { min-width: 0; flex: 1; }.ds-example-node-row .ds-node-name { color: var(--text, #21463a); font-size: 22px; line-height: 1.4; font-weight: 550; letter-spacing: -.02em; text-decoration: none; overflow-wrap: anywhere; }.ds-example-node-row .ds-node-name:hover { text-decoration: underline; }.ds-example-node-row .ds-node-id { color: var(--muted, #58714f); font-size: 11px; line-height: 1.7; font-family: ui-monospace, SFMono-Regular, Consolas, monospace; overflow-wrap: anywhere; }.ds-example-node-row .ds-node-title .ds-node-id { margin-top: 7px; }.ds-example-node-row .ds-node-state { display: contents; }.ds-example-node-row .ds-status { display: inline-flex; align-items: center; justify-content: center; gap: 7px; font-size: 11px; line-height: 1.5; font-weight: 550; white-space: nowrap; width: 67px; padding: 5px 9px; border: 1px solid #dbe3d4; border-radius: 4px; color: #5b7051; background: #f1f4ec; }.ds-example-node-row .ds-status::before { content: ""; width: 5px; height: 5px; flex: none; border-radius: 50%; background: currentColor; }.ds-example-node-row .ds-status.ds-online { background: #e9f0de; border-color: #c2d7b8; color: #426f45; }.ds-example-node-row .ds-last-seen { font-size: 13px; color: var(--muted, #58714f); font-variant-numeric: tabular-nums; }.ds-example-node-row .ds-icon { width: 22px; height: 22px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }.ds-example-node-row p { margin: 0; }.ds-example-node-row .ds-button { -webkit-tap-highlight-color: transparent; min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 12px; padding: 10px 16px; border: 1px solid #c8d8bf; border-radius: 6px; background: transparent; color: #42663c; text-decoration: none; font-size: 13px; font-weight: 550; line-height: 1.5; cursor: pointer; transition: background-color 160ms ease-out, border-color 160ms ease-out; }.ds-example-node-row .ds-button:hover { background: #e8efdf; border-color: #a9bea0; }.ds-example-node-row .ds-button:active { background: #dae5d0; }.ds-example-node-row .ds-button .ds-icon { width: 18px; height: 18px; }.ds-example-node-row .ds-open-node { background: var(--mint, #dfe9d6); border: 0; color: #315c3b; padding: 8px 16px; border-radius: 5px; font-size: 12px; gap: 13px; white-space: nowrap; }.ds-example-node-row .ds-open-node .ds-icon { width: 17px; }.ds-example-node-row .ds-open-node:hover { background: #cddfbe; }.ds-example-node-row .ds-menu { position: relative; flex: none; }.ds-example-node-row .ds-menu summary { list-style: none; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 12px; min-height: 44px; min-width: 44px; color: #4b6856; border-radius: 6px; }.ds-example-node-row .ds-menu summary::-webkit-details-marker { display: none; }.ds-example-node-row .ds-menu summary:hover { background: #e0e9da; }.ds-example-node-row .ds-menu[open] summary { background: #e0e9da; }.ds-example-node-row .ds-menu summary .ds-icon { width: 18px; height: 18px; }.ds-example-node-row .ds-menu-panel { position: absolute; z-index: 5; top: calc(100% + 3px); right: 0; width: 168px; padding: 6px; border-radius: 8px; background: var(--paper, #fbfcf7); box-shadow: 0 8px 28px -8px #18372355; }.ds-example-node-row .ds-menu-panel button { display: flex; justify-content: flex-start; width: 100%; border: 0; padding: 10px 13px; font-size: 12px; border-radius: 5px; }.ds-example-node-row .ds-menu-panel button.ds-danger { color: var(--danger, #934838); }.ds-example-node-row button { font: inherit; -webkit-tap-highlight-color: transparent; min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 12px; padding: 10px 16px; border: 1px solid #c8d8bf; border-radius: 6px; background: transparent; color: #42663c; text-decoration: none; font-size: 13px; font-weight: 550; line-height: 1.5; cursor: pointer; transition: background-color 160ms ease-out, border-color 160ms ease-out; }.ds-example-node-row button:hover { background: #e8efdf; border-color: #a9bea0; }.ds-example-node-row button:active { background: #dae5d0; }.ds-example-node-row :focus-visible { outline: 2px solid #547d52; outline-offset: 3px; }
@media (max-width: 950px) { .ds-example-node-row .ds-node { grid-template-columns: minmax(0, 1fr) 82px 94px 90px; column-gap: 16px; } .ds-example-node-row .ds-node-name { font-size: 19px; } } @media (max-width: 600px) { .ds-example-node-row .ds-node { grid-template-columns: minmax(0, 1fr) 74px; padding: 23px 0; gap: 9px 12px; } .ds-example-node-row .ds-node-main { grid-column: 1 / -1; align-items: flex-start; gap: 11px; } .ds-example-node-row .ds-node-main > .ds-node-icon { width: 25px; justify-content: flex-start; padding-top: 4px; } .ds-example-node-row .ds-node-icon .ds-icon { width: 20px; } .ds-example-node-row .ds-node-name { font-size: 17px; } .ds-example-node-row .ds-node-state { grid-column: 1; grid-row: 2; display: flex; align-items: center; flex-wrap: wrap; gap: 6px 9px; margin-left: 36px; } .ds-example-node-row .ds-status { width: 55px; font-size: 10px; gap: 4px; padding: 3px 6px; } .ds-example-node-row .ds-last-seen { font-size: 11px; } .ds-example-node-row .ds-open-node { grid-column: 2; grid-row: 2; padding: 6px 11px; font-size: 12px; gap: 8px; } .ds-example-node-row .ds-node-menu .ds-menu-panel { width: 145px; } }
@media (prefers-reduced-motion: reduce) { .ds-example-node-row *, .ds-example-node-row *::before, .ds-example-node-row *::after { transition: none !important; animation: none !important; } }
